 import { useState, useRef, useCallback, useEffect } from 'react';

const API_BASE = 'http://localhost:5001';

// ─── Field metadata ────────────────────────────────────────────────────────────
const FIELD_META = {
  shoot_height_cm:        { label: 'Shoot Height',        unit: 'cm', icon: 'ruler'    },
  trunk_circumference_cm: { label: 'Trunk Circumference', unit: 'cm', icon: 'circle'   },
  shoot_age_months:       { label: 'Shoot Age',           unit: 'mo', icon: 'calendar' },
  num_leaves:             { label: 'Leaf Count',          unit: '',   icon: 'leaf'     },
  leaf_color:             { label: 'Leaf Colour',         unit: '',   icon: 'palette'  },
  bark_texture:           { label: 'Bark Texture',        unit: '',   icon: 'texture'  },
  bark_color:             { label: 'Bark Colour',         unit: '',   icon: 'droplet'  },
  straightness:           { label: 'Straightness',        unit: '',   icon: 'line'     },
};

const MISSING_FIELD_TIPS = {
  "Shoot height (cm)":        "e.g. 'height 145 cm'",
  "Trunk circumference (cm)": "e.g. 'trunk 4 cm'",
  "Shoot age (months)":       "e.g. 'age 18 months'",
  "Number of leaves":         "e.g. '16 leaves'",
  "Leaf colour":              "e.g. 'yellowish green leaves'",
  "Bark colour":              "e.g. 'dark brown bark'",
  "Bark texture":             "e.g. 'rough and peeling'",
  "Shoot straightness":       "e.g. 'very straight'",
};

// ─── Verdict config ────────────────────────────────────────────────────────────
const VERDICT = {
  'Ready': {
    label:      'Ready for Harvest',
    sub:        'Coppice at 6 cm from ground at a 45° angle for best yield.',
    icon:       '✓',
    color:      '#22c55e',
    bgVar:      'var(--ch-success-bg)',
    borderVar:  'var(--ch-success-border)',
    textVar:    'var(--ch-success-text)',
    barColor:   '#22c55e',
  },
  'Borderline': {
    label:      'Borderline — Nearly Ready',
    sub:        'Re-assess in 2–6 weeks. Key indicators are still developing.',
    icon:       '◷',
    color:      '#f59e0b',
    bgVar:      'var(--ch-warning-bg)',
    borderVar:  'var(--ch-warning-border)',
    textVar:    'var(--ch-warning-text)',
    barColor:   '#f59e0b',
  },
  'Not Ready': {
    label:      'Not Ready Yet',
    sub:        'The shoot needs significantly more development. Check again in 6–8 weeks.',
    icon:       '✕',
    color:      '#3b82f6',
    bgVar:      'var(--ch-info-bg)',
    borderVar:  'var(--ch-info-border)',
    textVar:    'var(--ch-info-text)',
    barColor:   '#3b82f6',
  },
};

const CONF_BARS = [
  { key: 'Ready',      color: '#22c55e' },
  { key: 'Borderline', color: '#f59e0b' },
  { key: 'Not Ready',  color: '#3b82f6' },
];

const TIER_CONFIG = {
  high:     { label: 'High confidence',      colorVar: 'var(--ch-success-text)', bgVar: 'var(--ch-success-bg)' },
  medium:   { label: 'Medium confidence',    colorVar: 'var(--ch-warning-text)', bgVar: 'var(--ch-warning-bg)' },
  low:      { label: 'Low confidence',       colorVar: 'var(--ch-danger-text)',  bgVar: 'var(--ch-danger-bg)'  },
  very_low: { label: 'Very low confidence',  colorVar: 'var(--ch-danger-text)',  bgVar: 'var(--ch-danger-bg)'  },
};

const URGENCY_LABEL = {
  high:   'Harvest Now',
  medium: 'Monitor Closely',
  low:    'Allow Development',
};

// ─── Minimal SVG icons ────────────────────────────────────────────────────────
function Icon({ name, size = 14 }) {
  const s = { width: size, height: size, display: 'inline-block', flexShrink: 0, verticalAlign: 'middle' };
  const icons = {
    leaf:     <><path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10z"/><path d="M2 21c0-3 1.85-5.36 5.08-6C9.5 14.52 12 13 13 12"/></>,
    ruler:    <><path d="M21.3 8.7 8.7 21.3c-.39.39-1.02.39-1.41 0l-6.3-6.3a1 1 0 0 1 0-1.41L13.6 1.01a1 1 0 0 1 1.41 0l6.3 6.3c.38.38.38 1.01-.01 1.39z"/><path d="m7.5 10.5 2 2M10.5 7.5l2 2M13.5 4.5l2 2M4.5 13.5l2 2"/></>,
    circle:   <><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="4"/></>,
    calendar: <><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></>,
    palette:  <><circle cx="12" cy="12" r="10"/><path d="M12 8c-2.2 0-4 1.8-4 4 0 .93.32 1.78.84 2.46L8 16h8l-.84-1.54A4 4 0 0 0 16 12c0-2.2-1.8-4-4-4z"/></>,
    texture:  <><path d="M4 6h16M4 10h16M4 14h16M4 18h16"/></>,
    droplet:  <><path d="M12 2.69l5.66 5.66a8 8 0 1 1-11.31 0z"/></>,
    line:     <><path d="M2 12h20"/></>,
    mic:      <><path d="M12 2a3 3 0 0 1 3 3v7a3 3 0 0 1-6 0V5a3 3 0 0 1 3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><path d="M12 19v3M9 22h6"/></>,
    stop:     null,
    search:   <><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></>,
    info:     <><circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/></>,
    chart:    <><path d="M3 3v18h18"/><path d="M18 9l-5 5-4-4-3 3"/></>,
    eye:      <><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/></>,
    warn:     <><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3z"/><path d="M12 9v4M12 17h.01"/></>,
    sparkle:  <><path d="M9.937 15.5A2 2 0 0 0 8.5 14.063l-6.135-1.582a.5.5 0 0 1 0-.962L8.5 9.936A2 2 0 0 0 9.937 8.5l1.582-6.135a.5.5 0 0 1 .963 0L14.063 8.5A2 2 0 0 0 15.5 9.937l6.135 1.581a.5.5 0 0 1 0 .964L15.5 14.063a2 2 0 0 0-1.437 1.437l-1.582 6.135a.5.5 0 0 1-.963 0z"/></>,
    plus:     <><path d="M5 12h14M12 5v14"/></>,
    shield:   <><path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/></>,
    heatmap:  <><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></>,
    list:     <><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></>,
    clock:    <><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></>,
    spin:     null,
  };

  if (name === 'stop') {
    return (
      <svg style={s} viewBox="0 0 24 24" fill="currentColor">
        <rect x="6" y="6" width="12" height="12" rx="2" />
      </svg>
    );
  }

  return (
    <svg style={s} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth="1.8"
      strokeLinecap="round" strokeLinejoin="round">
      {icons[name] || icons.info}
    </svg>
  );
}

// ─── Global CSS (injected once) ───────────────────────────────────────────────
const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Geist:wght@300;400;500;600&family=Geist+Mono:wght@400;500&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --ch-bg:            #f8f7f4;
    --ch-surface:       #ffffff;
    --ch-surface2:      #f2f1ee;
    --ch-surface3:      #eae9e5;
    --ch-border:        rgba(0,0,0,0.08);
    --ch-border2:       rgba(0,0,0,0.13);
    --ch-text:          #111210;
    --ch-text2:         #4a4a48;
    --ch-muted:         #8a8a85;
    --ch-accent:        #22c55e;
    --ch-radius:        10px;
    --ch-radius-lg:     14px;
    --ch-ease:          cubic-bezier(0.4,0,0.2,1);

    --ch-success-bg:    #f0fdf4;
    --ch-success-border:#bbf7d0;
    --ch-success-text:  #15803d;
    --ch-warning-bg:    #fffbeb;
    --ch-warning-border:#fde68a;
    --ch-warning-text:  #b45309;
    --ch-danger-bg:     #fff1f2;
    --ch-danger-border: #fecdd3;
    --ch-danger-text:   #be123c;
    --ch-info-bg:       #eff6ff;
    --ch-info-border:   #bfdbfe;
    --ch-info-text:     #1d4ed8;
  }

  @media (prefers-color-scheme: dark) {
    :root {
      --ch-bg:            #0e0f0d;
      --ch-surface:       #161714;
      --ch-surface2:      #1c1d1a;
      --ch-surface3:      #222320;
      --ch-border:        rgba(255,255,255,0.07);
      --ch-border2:       rgba(255,255,255,0.12);
      --ch-text:          #edecea;
      --ch-text2:         #a8a8a3;
      --ch-muted:         #5c5c58;

      --ch-success-bg:    #052e16;
      --ch-success-border:#14532d;
      --ch-success-text:  #4ade80;
      --ch-warning-bg:    #1c1400;
      --ch-warning-border:#713f12;
      --ch-warning-text:  #fbbf24;
      --ch-danger-bg:     #1c0a0a;
      --ch-danger-border: #7f1d1d;
      --ch-danger-text:   #f87171;
      --ch-info-bg:       #0a1628;
      --ch-info-border:   #1e3a5f;
      --ch-info-text:     #60a5fa;
    }
  }

  html, body, #root { height: 100%; overflow: hidden; }

  body {
    font-family: 'Geist', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--ch-bg);
    color: var(--ch-text);
    -webkit-font-smoothing: antialiased;
  }

  ::-webkit-scrollbar { width: 3px; }
  ::-webkit-scrollbar-thumb { background: var(--ch-border2); border-radius: 3px; }
  ::-webkit-scrollbar-track { background: transparent; }

  @keyframes fadeUp  { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
  @keyframes fadeIn  { from { opacity: 0; } to { opacity: 1; } }
  @keyframes spin    { to { transform: rotate(360deg); } }
  @keyframes barIn   { from { transform: scaleX(0); } to { transform: scaleX(1); } }
  @keyframes recPulse{ 0%,100%{ box-shadow: 0 0 0 0 rgba(239,68,68,.4); } 60%{ box-shadow: 0 0 0 7px rgba(239,68,68,0); } }
  @keyframes shimmer { 0%{ background-position: -500px 0; } 100%{ background-position: 500px 0; } }

  /* ── Layout ── */
  .ch-app { display: grid; grid-template-rows: 48px 1fr; height: 100vh; overflow: hidden; }

  /* ── Topbar ── */
  .ch-topbar { display: flex; align-items: center; gap: 10px; padding: 0 18px; background: var(--ch-surface); border-bottom: 1px solid var(--ch-border); z-index: 20; }
  .ch-topbar-logo { width: 26px; height: 26px; border-radius: 7px; background: #15803d; display: flex; align-items: center; justify-content: center; color: #fff; flex-shrink: 0; }
  .ch-topbar-name { font-size: .875rem; font-weight: 600; flex: 1; letter-spacing: -.01em; }
  .ch-topbar-badge { font-size: .65rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; padding: 2px 8px; border-radius: 20px; background: var(--ch-success-bg); color: var(--ch-success-text); border: 1px solid var(--ch-success-border); }

  /* ── Two-panel body ── */
  .ch-panels { display: grid; grid-template-columns: 320px 1fr; overflow: hidden; height: 100%; }

  /* ── Left panel ── */
  .ch-left { display: flex; flex-direction: column; background: var(--ch-surface); border-right: 1px solid var(--ch-border); overflow-y: auto; overflow-x: hidden; }
  .ch-left-hero { padding: 18px 18px 14px; border-bottom: 1px solid var(--ch-border); background: var(--ch-surface); }
  .ch-left-eyebrow { display: flex; align-items: center; gap: 5px; font-size: .63rem; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--ch-accent); margin-bottom: 6px; }
  .ch-left-eyebrow-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--ch-accent); animation: recPulse 2s ease infinite; }
  .ch-left-title { font-size: 1.05rem; font-weight: 600; letter-spacing: -.02em; line-height: 1.25; color: var(--ch-text); margin-bottom: 4px; }
  .ch-left-sub { font-size: .72rem; color: var(--ch-muted); line-height: 1.6; }

  /* ── Sections ── */
  .ch-section { padding: 14px 16px; border-bottom: 1px solid var(--ch-border); }
  .ch-section:last-child { border-bottom: none; flex: 1; }
  .ch-sec-lbl { display: flex; align-items: center; gap: 6px; font-size: .65rem; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--ch-muted); margin-bottom: 9px; }

  /* ── Textarea ── */
  .ch-ta { width: 100%; min-height: 100px; background: var(--ch-surface2); color: var(--ch-text); border: 1px solid var(--ch-border2); border-radius: var(--ch-radius); padding: 10px 12px; font-family: 'Geist', sans-serif; font-size: .82rem; line-height: 1.65; resize: none; outline: none; transition: border-color .15s; }
  .ch-ta::placeholder { color: var(--ch-muted); font-size: .76rem; }
  .ch-ta:focus { border-color: #22c55e; box-shadow: 0 0 0 3px rgba(34,197,94,.08); }

  /* ── Hint ── */
  .ch-hint { display: flex; align-items: center; gap: 5px; font-size: .65rem; color: var(--ch-muted); margin: 6px 0 10px; }

  /* ── Buttons ── */
  .ch-btn-primary { width: 100%; padding: 9px 14px; border: none; border-radius: var(--ch-radius); cursor: pointer; font-family: 'Geist', sans-serif; font-size: .82rem; font-weight: 600; display: flex; align-items: center; justify-content: center; gap: 7px; position: relative; overflow: hidden; transition: all .18s var(--ch-ease); background: #15803d; color: #fff; letter-spacing: -.01em; }
  .ch-btn-primary:not(:disabled):hover { background: #166534; transform: translateY(-1px); box-shadow: 0 3px 12px rgba(21,128,61,.25); }
  .ch-btn-primary:not(:disabled):active { transform: translateY(0); }
  .ch-btn-primary:disabled { background: var(--ch-surface3); color: var(--ch-muted); cursor: not-allowed; box-shadow: none; }
  .ch-btn-shimmer { position: absolute; inset: 0; background: linear-gradient(90deg, transparent, rgba(255,255,255,.18), transparent); background-size: 500px; animation: shimmer 1.5s infinite; }

  .ch-btn-mic { width: 100%; padding: 7px 14px; border: 1px solid var(--ch-border2); border-radius: var(--ch-radius); cursor: pointer; font-family: 'Geist', sans-serif; font-size: .78rem; font-weight: 500; display: flex; align-items: center; justify-content: center; gap: 7px; margin-top: 6px; background: transparent; color: var(--ch-text2); transition: all .15s; }
  .ch-btn-mic:hover { background: var(--ch-surface2); border-color: var(--ch-border2); }
  .ch-btn-mic.rec { border-color: #ef4444; color: #ef4444; animation: recPulse 1.4s infinite; }

  /* ── Spinner ── */
  .ch-spin { width: 13px; height: 13px; border-radius: 50%; border: 2px solid rgba(255,255,255,.3); border-top-color: #fff; animation: spin .65s linear infinite; flex-shrink: 0; }
  .ch-spin-green { width: 13px; height: 13px; border-radius: 50%; border: 2px solid var(--ch-border2); border-top-color: var(--ch-accent); animation: spin .65s linear infinite; flex-shrink: 0; }

  /* ── Field pills ── */
  .ch-pills { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
  .ch-pill { background: var(--ch-surface2); border: 1px solid var(--ch-border); border-radius: 8px; padding: 8px 10px; animation: fadeUp .3s var(--ch-ease) both; }
  .ch-pill-lbl { display: flex; align-items: center; gap: 4px; font-size: .6rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--ch-muted); margin-bottom: 3px; }
  .ch-pill-val { font-size: .82rem; font-weight: 600; color: var(--ch-text); font-family: 'Geist Mono', monospace; }

  /* ── Completeness ── */
  .ch-comp-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 7px; }
  .ch-comp-badge { font-size: .65rem; font-weight: 600; padding: 2px 8px; border-radius: 20px; }
  .ch-comp-pct { font-size: .75rem; font-weight: 600; font-family: 'Geist Mono', monospace; }
  .ch-progress { height: 4px; background: var(--ch-surface3); border-radius: 4px; overflow: hidden; margin: 0 0 8px; }
  .ch-progress-fill { height: 100%; background: var(--ch-accent); border-radius: 4px; transition: width .6s cubic-bezier(.34,1.56,.64,1); transform-origin: left; }
  .ch-comp-count { font-size: .67rem; color: var(--ch-muted); margin-bottom: 8px; }
  .ch-missing-hd { font-size: .6rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--ch-muted); margin-bottom: 6px; }
  .ch-missing-item { display: flex; gap: 7px; align-items: flex-start; padding: 6px 0; }
  .ch-missing-dot { width: 4px; height: 4px; border-radius: 50%; background: #f59e0b; flex-shrink: 0; margin-top: 5px; }
  .ch-missing-field { font-size: .73rem; font-weight: 500; color: var(--ch-text2); }
  .ch-missing-tip { font-size: .64rem; color: var(--ch-muted); margin-top: 1px; }

  /* ── Right panel ── */
  .ch-right { overflow-y: auto; overflow-x: hidden; background: var(--ch-bg); }
  .ch-right-inner { padding: 18px; display: flex; flex-direction: column; gap: 12px; min-height: 100%; }

  /* ── Placeholder ── */
  .ch-placeholder { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; opacity: .38; padding: 48px 24px; text-align: center; }
  .ch-placeholder-icon { width: 44px; height: 44px; border-radius: 12px; background: var(--ch-surface3); display: flex; align-items: center; justify-content: center; color: var(--ch-muted); }
  .ch-placeholder p { font-size: .78rem; color: var(--ch-muted); line-height: 1.65; max-width: 200px; }

  /* ── Loading ── */
  .ch-loading { display: flex; align-items: center; gap: 9px; background: var(--ch-surface); border: 1px solid var(--ch-border); border-radius: var(--ch-radius-lg); padding: 12px 14px; font-size: .78rem; color: var(--ch-text2); animation: fadeIn .2s ease; }

  /* ── Error ── */
  .ch-error { background: var(--ch-danger-bg); border: 1px solid var(--ch-danger-border); border-radius: var(--ch-radius-lg); padding: 13px 15px; animation: fadeUp .3s ease; }
  .ch-error-head { display: flex; align-items: center; gap: 6px; font-size: .78rem; font-weight: 600; color: var(--ch-danger-text); margin-bottom: 4px; }
  .ch-error-body { font-size: .74rem; color: var(--ch-danger-text); opacity: .8; line-height: 1.55; }
  .ch-error-tip { font-size: .68rem; color: var(--ch-danger-text); opacity: .55; margin-top: 4px; }

  /* ── Verdict ── */
  .ch-verdict { border-radius: var(--ch-radius-lg); padding: 16px; display: flex; align-items: flex-start; gap: 12px; border: 1px solid; animation: fadeUp .35s var(--ch-ease); }
  .ch-verdict-ico { width: 38px; height: 38px; border-radius: 9px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 700; background: rgba(255,255,255,.12); }
  .ch-verdict-label { font-size: 1rem; font-weight: 600; letter-spacing: -.02em; margin-bottom: 3px; }
  .ch-verdict-sub { font-size: .74rem; line-height: 1.55; opacity: .72; }

  /* ── Cards ── */
  .ch-card { background: var(--ch-surface); border: 1px solid var(--ch-border); border-radius: var(--ch-radius-lg); overflow: hidden; animation: fadeUp .38s var(--ch-ease) both; }
  .ch-card-hdr { display: flex; align-items: center; gap: 8px; padding: 11px 14px; border-bottom: 1px solid var(--ch-border); font-size: .65rem; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--ch-muted); background: var(--ch-surface); }
  .ch-card-body { padding: 12px 14px; }

  /* ── Confidence bars ── */
  .ch-conf-row { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
  .ch-conf-row:last-child { margin-bottom: 0; }
  .ch-conf-name { width: 88px; font-size: .72rem; color: var(--ch-text2); flex-shrink: 0; }
  .ch-conf-track { flex: 1; height: 4px; background: var(--ch-surface2); border-radius: 4px; overflow: hidden; }
  .ch-conf-fill { height: 100%; border-radius: 4px; transition: width .8s cubic-bezier(.34,1.56,.64,1); }
  .ch-conf-pct { width: 34px; text-align: right; font-size: .72rem; font-weight: 600; font-family: 'Geist Mono', monospace; }

  /* ── Grad-CAM ── */
  .ch-cam-desc { font-size: .7rem; color: var(--ch-muted); line-height: 1.55; margin-bottom: 12px; }
  .ch-cam-row { margin-bottom: 10px; }
  .ch-cam-row:last-child { margin-bottom: 0; }
  .ch-cam-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px; }
  .ch-cam-label { display: flex; align-items: center; gap: 5px; font-size: .76rem; font-weight: 600; color: var(--ch-text); }
  .ch-cam-badge { font-size: .58rem; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; padding: 1px 5px; border-radius: 4px; }
  .ch-cam-badge.supports { background: var(--ch-success-bg); color: var(--ch-success-text); border: 1px solid var(--ch-success-border); }
  .ch-cam-badge.opposes  { background: var(--ch-danger-bg);  color: var(--ch-danger-text);  border: 1px solid var(--ch-danger-border); }
  .ch-cam-badge.neutral  { background: var(--ch-surface2);   color: var(--ch-muted); border: 1px solid var(--ch-border); }
  .ch-cam-val { font-size: .68rem; color: var(--ch-muted); font-family: 'Geist Mono', monospace; }
  .ch-cam-track { height: 5px; background: var(--ch-surface2); border-radius: 4px; overflow: hidden; }
  .ch-cam-fill { height: 100%; border-radius: 4px; transition: width .8s cubic-bezier(.34,1.56,.64,1); opacity: .85; }
  .ch-cam-exp { font-size: .68rem; color: var(--ch-muted); margin-top: 3px; line-height: 1.5; }

  /* ── Reasons ── */
  .ch-reasons { display: flex; flex-direction: column; gap: 6px; }
  .ch-reason { display: flex; gap: 9px; align-items: flex-start; background: var(--ch-surface2); border: 1px solid var(--ch-border); border-radius: 8px; padding: 9px 11px; animation: fadeUp .3s var(--ch-ease) both; }
  .ch-reason-dot { width: 4px; height: 4px; border-radius: 50%; background: var(--ch-accent); flex-shrink: 0; margin-top: 7px; }
  .ch-reason-txt { font-size: .76rem; line-height: 1.62; color: var(--ch-text2); }

  /* ── Guidelines ── */
  .ch-guide { background: var(--ch-surface); border: 1px solid var(--ch-border); border-radius: var(--ch-radius-lg); overflow: hidden; animation: fadeUp .4s var(--ch-ease) both; }
  .ch-guide-hdr { display: flex; align-items: center; justify-content: space-between; padding: 11px 14px; border-bottom: 1px solid var(--ch-border); background: var(--ch-surface2); }
  .ch-guide-hdr-left { display: flex; align-items: center; gap: 7px; font-size: .65rem; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--ch-muted); }
  .ch-guide-urgency { font-size: .65rem; font-weight: 600; padding: 2px 8px; border-radius: 20px; border: 1px solid; }
  .ch-guide-steps { padding: 12px 14px; display: flex; flex-direction: column; gap: 6px; }
  .ch-guide-step { display: flex; gap: 9px; align-items: flex-start; font-size: .76rem; line-height: 1.58; color: var(--ch-text2); }
  .ch-guide-num { width: 18px; height: 18px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: .6rem; font-weight: 700; flex-shrink: 0; margin-top: 2px; background: var(--ch-success-bg); color: var(--ch-success-text); }
  .ch-guide-recheck { margin: 0 14px 12px; padding: 7px 11px; border-radius: 8px; font-size: .72rem; font-weight: 500; display: flex; align-items: center; gap: 7px; }

  /* ── Section divider ── */
  .ch-divider { display: flex; align-items: center; gap: 10px; font-size: .6rem; font-weight: 600; letter-spacing: .09em; text-transform: uppercase; color: var(--ch-muted); animation: fadeIn .3s ease; }
  .ch-divider::before, .ch-divider::after { content: ''; flex: 1; height: 1px; background: var(--ch-border); }

  /* ── Footer ── */
  .ch-footer { text-align: center; font-size: .65rem; color: var(--ch-muted); line-height: 1.65; padding: 4px 0 8px; animation: fadeIn .5s ease; }

  /* ── Responsive ── */
  @media (max-width: 600px) {
    .ch-panels { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }
    .ch-left  { max-height: 55vh; border-right: none; border-bottom: 1px solid var(--ch-border); }
    .ch-right { min-height: 45vh; }
    .ch-pills { grid-template-columns: 1fr 1fr; }
  }
  @media (min-width: 1100px) {
    .ch-panels { grid-template-columns: 360px 1fr; }
  }
`;

function useInjectCSS() {
  useEffect(() => {
    const id = 'ch-styles-v2';
    if (!document.getElementById(id)) {
      const el = document.createElement('style');
      el.id = id;
      el.textContent = CSS;
      document.head.appendChild(el);
    }
    return () => {}; // keep styles across HMR
  }, []);
}

// ─── Sub-components ────────────────────────────────────────────────────────────

function Topbar() {
  return (
    <div className="ch-topbar">
      <div className="ch-topbar-logo">
        <Icon name="leaf" size={14} />
      </div>
      <div className="ch-topbar-name">CinnamonHarvest</div>
      <div className="ch-topbar-badge">AI · CCGI</div>
    </div>
  );
}

function InputSection({ text, setText, loading, recording, onMic, onAnalyse }) {
  return (
    <>
      {/* Hero */}
      <div className="ch-left-hero">
        <div className="ch-left-eyebrow">
          <div className="ch-left-eyebrow-dot" />
          Ceylon Cinnamon · CCGI
        </div>
        <div className="ch-left-title">Harvest Readiness<br />Checker</div>
        <div className="ch-left-sub">
          Describe a shoot — the AI predicts its stage and gives CCGI-aligned next steps.
        </div>
      </div>

      {/* Input */}
      <div className="ch-section">
        <div className="ch-sec-lbl">
          <Icon name="sparkle" size={12} />
          Shoot description
        </div>
        <textarea
          className="ch-ta"
          value={text}
          onChange={e => setText(e.target.value)}
          onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onAnalyse(); } }}
          placeholder={'e.g. "Height 155 cm, trunk 4.2 cm, age 20 months, brownish green leaves, rough dark brown bark, 18 leaves, very straight"'}
        />
        <div className="ch-hint">
          <Icon name="info" size={11} />
          More fields = higher confidence · Enter to analyse
        </div>
        <button
          className="ch-btn-primary"
          disabled={loading || !text.trim()}
          onClick={onAnalyse}
        >
          {loading && <div className="ch-btn-shimmer" />}
          {loading
            ? <><div className="ch-spin" />Analysing shoot…</>
            : <><Icon name="search" size={14} />Check harvest readiness</>}
        </button>
        <button
          className={`ch-btn-mic${recording ? ' rec' : ''}`}
          onClick={onMic}
          title={recording ? 'Stop recording' : 'Speak measurements'}
        >
          <Icon name={recording ? 'stop' : 'mic'} size={14} />
          {recording ? 'Stop recording' : 'Speak measurements'}
        </button>
      </div>
    </>
  );
}

function DetectedFields({ fields }) {
  const entries = Object.entries(fields).filter(([, v]) => v != null);
  if (!entries.length) return null;
  return (
    <div className="ch-section">
      <div className="ch-sec-lbl"><Icon name="eye" size={12} />Detected values</div>
      <div className="ch-pills">
        {entries.map(([k, val], i) => {
          const m = FIELD_META[k] || { label: k, unit: '', icon: 'info' };
          return (
            <div className="ch-pill" key={k} style={{ animationDelay: `${i * 0.04}s` }}>
              <div className="ch-pill-lbl">
                <Icon name={m.icon} size={10} />
                {m.label}
              </div>
              <div className="ch-pill-val">{String(val)}{m.unit ? ` ${m.unit}` : ''}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function CompletenessSection({ completeness }) {
  if (!completeness) return null;
  const { total_provided, total_fields, tier, missing_fields } = completeness;
  const tc = TIER_CONFIG[tier] || TIER_CONFIG.low;
  const pct = Math.round((total_provided / total_fields) * 100);

  return (
    <div className="ch-section">
      <div className="ch-sec-lbl">
        <Icon name="shield" size={12} />
        Data completeness
      </div>
      <div className="ch-comp-row">
        <span
          className="ch-comp-badge"
          style={{ background: tc.bgVar, color: tc.colorVar }}
        >{tc.label}</span>
        <span className="ch-comp-pct" style={{ color: tc.colorVar }}>{pct}%</span>
      </div>
      <div className="ch-progress">
        <div className="ch-progress-fill" style={{ width: `${pct}%` }} />
      </div>
      <div className="ch-comp-count">{total_provided} of {total_fields} fields provided</div>
      {missing_fields?.length > 0 && (
        <>
          <div className="ch-missing-hd">
            <Icon name="plus" size={10} /> Add to improve accuracy
          </div>
          {missing_fields.map(f => (
            <div className="ch-missing-item" key={f}>
              <div className="ch-missing-dot" />
              <div>
                <div className="ch-missing-field">{f}</div>
                <div className="ch-missing-tip">{MISSING_FIELD_TIPS[f] || ''}</div>
              </div>
            </div>
          ))}
        </>
      )}
    </div>
  );
}

function VerdictBanner({ prediction }) {
  const v = VERDICT[prediction] || VERDICT['Not Ready'];
  return (
    <div
      className="ch-verdict"
      style={{ background: v.bgVar, borderColor: v.borderVar, color: v.textVar }}
    >
      <div className="ch-verdict-ico" style={{ color: v.textVar }}>
        {v.icon}
      </div>
      <div>
        <div className="ch-verdict-label">{v.label}</div>
        <div className="ch-verdict-sub">{v.sub}</div>
      </div>
    </div>
  );
}

function ConfidenceCard({ confidence }) {
  return (
    <div className="ch-card" style={{ animationDelay: '0.06s' }}>
      <div className="ch-card-hdr"><Icon name="chart" size={13} />Model confidence</div>
      <div className="ch-card-body">
        {CONF_BARS.map(({ key, color }) => (
          <div className="ch-conf-row" key={key}>
            <div className="ch-conf-name">{key}</div>
            <div className="ch-conf-track">
              <div
                className="ch-conf-fill"
                style={{ width: `${confidence?.[key] ?? 0}%`, background: color }}
              />
            </div>
            <div className="ch-conf-pct" style={{ color }}>
              {Math.round(confidence?.[key] ?? 0)}%
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function GradCAMCard({ attributions, prediction }) {
  if (!attributions?.length) return null;
  const v = VERDICT[prediction] || VERDICT['Not Ready'];
  const maxAttr = Math.max(...attributions.map(a => a.attribution), 1);

  return (
    <div className="ch-card" style={{ animationDelay: '0.1s' }}>
      <div className="ch-card-hdr"><Icon name="heatmap" size={13} />Feature attribution (Grad-CAM)</div>
      <div className="ch-card-body">
        <div className="ch-cam-desc">
          How much each feature influenced the&nbsp;
          <strong style={{ color: v.color }}>{prediction}</strong> prediction.
          Longer bar = stronger influence.
        </div>
        {attributions.map((a, i) => {
          const pct = Math.round((a.attribution / maxAttr) * 100);
          const barColor =
            a.direction === 'supports' ? v.barColor
            : a.direction === 'opposes' ? '#ef4444'
            : 'var(--ch-muted)';
          return (
            <div className="ch-cam-row" key={a.feature} style={{ animationDelay: `${i * 0.05}s` }}>
              <div className="ch-cam-hdr">
                <div className="ch-cam-label">
                  {a.label}
                  <span className={`ch-cam-badge ${a.direction}`}>{a.direction}</span>
                </div>
                <span className="ch-cam-val">
                  {typeof a.value === 'number' ? a.value : `"${a.value}"`}
                </span>
              </div>
              <div className="ch-cam-track">
                <div className="ch-cam-fill" style={{ width: `${pct}%`, background: barColor }} />
              </div>
              <div className="ch-cam-exp">{a.explanation}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ReasonsCard({ reasons }) {
  if (!reasons?.length) return null;
  return (
    <div className="ch-card" style={{ animationDelay: '0.13s' }}>
      <div className="ch-card-hdr"><Icon name="info" size={13} />Analysis details</div>
      <div className="ch-card-body">
        <div className="ch-reasons">
          {reasons.map((r, i) => (
            <div className="ch-reason" key={i} style={{ animationDelay: `${i * 0.05}s` }}>
              <div className="ch-reason-dot" />
              <div className="ch-reason-txt">{r}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function GuidelinesCard({ guidelines, prediction }) {
  if (!guidelines) return null;
  const v = VERDICT[prediction] || VERDICT['Not Ready'];
  const urgencyLabel = URGENCY_LABEL[guidelines.urgency] || 'Review';

  return (
    <div className="ch-guide" style={{ animationDelay: '0.17s' }}>
      <div className="ch-guide-hdr">
        <div className="ch-guide-hdr-left">
          <Icon name="list" size={13} />
          CCGI next steps
        </div>
        <span
          className="ch-guide-urgency"
          style={{ background: v.bgVar, color: v.textVar, borderColor: v.borderVar }}
        >
          {urgencyLabel}
        </span>
      </div>
      <div className="ch-guide-steps">
        {guidelines.steps?.map((step, i) => (
          <div className="ch-guide-step" key={i} style={{ animationDelay: `${i * 0.05}s` }}>
            <div className="ch-guide-num">{i + 1}</div>
            <div>{step.replace(/^\p{Emoji}\s*/u, '')}</div>
          </div>
        ))}
      </div>
      {guidelines.recheck && (
        <div
          className="ch-guide-recheck"
          style={{ background: v.bgVar, color: v.textVar, border: `1px solid ${v.borderVar}` }}
        >
          <Icon name="clock" size={13} />
          Re-assess in approximately <strong>{guidelines.recheck}</strong>
        </div>
      )}
    </div>
  );
}

function ResultPanel({ result }) {
  return (
    <>
      <div className="ch-divider">Result</div>
      <VerdictBanner prediction={result.prediction} />
      <ConfidenceCard confidence={result.confidence} />
      <GradCAMCard attributions={result.attributions} prediction={result.prediction} />
      <ReasonsCard reasons={result.reasons} />
      {result.guidelines && (
        <>
          <div className="ch-divider" style={{ animationDelay: '0.15s' }}>Guidelines</div>
          <GuidelinesCard guidelines={result.guidelines} prediction={result.prediction} />
        </>
      )}
      <div className="ch-footer">
        CinnamonHarvest AI · Ceylon Cinnamon Growers Institute data · 78% accuracy (5-fold CV)<br />
        For guidance only — confirm with a field agronomist before harvest.
      </div>
    </>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function CinnamonHarvest() {
  useInjectCSS();

  const [text, setText]         = useState('');
  const [loading, setLoading]   = useState(false);
  const [statusMsg, setMsg]     = useState('');
  const [error, setError]       = useState('');
  const [fields, setFields]     = useState(null);
  const [completeness, setComp] = useState(null);
  const [result, setResult]     = useState(null);
  const [recording, setRec]     = useState(false);
  const recRef = useRef(null);

  const toggleMic = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input not supported in this browser. Use Chrome or Edge.'); return; }
    if (recording) { recRef.current?.stop(); setRec(false); return; }
    const rec = new SR();
    rec.lang = 'en-US'; rec.interimResults = true; rec.continuous = true;
    recRef.current = rec;
    const base = text;
    rec.onresult = e => {
      let interim = '', final = base;
      for (const r of e.results) {
        if (r.isFinal) final += (final ? ' ' : '') + r[0].transcript;
        else interim = r[0].transcript;
      }
      setText(final + (interim ? ' ' + interim : ''));
    };
    rec.onerror = () => setRec(false);
    rec.onend   = () => setRec(false);
    rec.start(); setRec(true);
  }, [recording, text]);

  const analyse = useCallback(async () => {
    if (!text.trim() || loading) return;
    setLoading(true);
    setError('');
    setResult(null);
    setFields(null);
    setComp(null);
    try {
      setMsg('Reading your description…');
      const pr = await fetch(`${API_BASE}/api/parse`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text }),
      });
      if (!pr.ok) throw new Error(`Parse error (${pr.status})`);
      const { fields: pf, completeness: pc } = await pr.json();
      setFields(pf);
      setComp(pc);

      setMsg('Running harvest readiness model…');
      const rr = await fetch(`${API_BASE}/api/predict`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: pf, completeness: pc }),
      });
      if (!rr.ok) {
        const body = await rr.json();
        if (body.error === 'insufficient_data') throw new Error(body.message || 'Not enough data to predict.');
        throw new Error(`Predict error (${rr.status})`);
      }
      setResult(await rr.json());
      setMsg('');
    } catch (e) {
      setError(e.message);
      setMsg('');
    } finally {
      setLoading(false);
    }
  }, [text, loading]);

  return (
    <div className="ch-app">
      <Topbar />
      <div className="ch-panels">

        {/* ── Left sidebar ── */}
        <div className="ch-left">
          <InputSection
            text={text} setText={setText}
            loading={loading} recording={recording}
            onMic={toggleMic} onAnalyse={analyse}
          />
          {fields      && <DetectedFields fields={fields} />}
          {completeness && <CompletenessSection completeness={completeness} />}
        </div>

        {/* ── Right results panel ── */}
        <div className="ch-right">
          <div className="ch-right-inner">
            {!loading && !error && !result && (
              <div className="ch-placeholder">
                <div className="ch-placeholder-icon">
                  <Icon name="leaf" size={22} />
                </div>
                <p>Describe a cinnamon shoot on the left. The AI will predict harvest readiness and explain its reasoning.</p>
              </div>
            )}

            {loading && statusMsg && (
              <div className="ch-loading">
                <div className="ch-spin-green" />
                {statusMsg}
              </div>
            )}

            {error && (
              <div className="ch-error">
                <div className="ch-error-head"><Icon name="warn" size={14} />Error</div>
                <div className="ch-error-body">{error}</div>
                <div className="ch-error-tip">Make sure Flask backend is running at {API_BASE}</div>
              </div>
            )}

            {result && <ResultPanel result={result} />}
          </div>
        </div>

      </div>
    </div>
  );
}
